// POST https://bsc-dataseed.bnbchain.org
// {"jsonrpc":"2.0","id":1,"method":"eth_getLogs","params":[{"fromBlock":"0x...","toBlock":"0x...","address":"0xfD5840Cd36d94D7229439859C0112a4185BC0255","topics":["0x1a2a22cb..."]}]}
// -> identical for spans of 1, 10, 100, 500, 1000, 2000, 5000, 10000, 50000 blocks:
{"jsonrpc": "2.0", "id": 1, "error": {"code": -32005, "message": "limit exceeded"}}

type BidBlockArgs struct {
    BidBlock  *BidBlock
    Signature hexutil.Bytes
}

type BidBlock struct {
    Header       *types.Header
    Transactions []hexutil.Bytes
    Sidecars     BlobSidecars
}
// Signature covers rlpHash(BidBlock).
// Builders poll GET /eth/v1/builder/permission to check SendBidBlock access.
// Revocation: 24h on InsertChain failure; one epoch if avg gas price < validator minimum.

POST https://api.blxrbdn.com        (or wss://api.blxrbdn.com/ws)
Authorization: <your-auth-header>

{
  "id": "1",
  "method": "blxr_submit_bundle",
  "params": {
    "txs": ["<signed raw tx hex>", "..."],
    "blockchain_network": "BSC-Mainnet",
    "max_block_number": 0,
    "reverting_tx_hashes": ["0x..."],
    "max_timestamp": 0,
    "mev_builders": {},
    "no_merge": false,
    "backrunme_reward_address": "0x..."
  }
}

// mev_builders keys: bloxroute (default) | all | 48club | blockrazor | jetbldr | nodereal
// default max_block_number = current block + 40
// max 2 txs per bundle without the Bundle Size Add-on; Cloud API only

{
  "jsonrpc": "2.0",
  "id": "1",
  "method": "eth_sendBundle",
  "params": [
    {
      "txs": ["0x…f1", "0x…b7"],
      "backrunTarget": "hash (optional)",
      "maxBlockNumber": "uint64 (optional)",
      "maxTimestamp": "uint64 (optional)",
      "revertingTxHashes": ["0x…1a", "0x…2b"],
      "noMerge": "bool (optional)",
      "positionFirst": "bool (optional)",
      "48spSign": "hex (optional)"
    }
  ]
}

// Auction sort key:
//   (sum of gas fees from non-pool transactions x 0.9) + BNB transferred to Builder Control EOA
// Builder Control EOA: 0x4848489f0b2BEdd788c696e2D79b6b69D7484848
// The 0.9 factor accounts for BEP95 (10% of gas fees are burnt).

import { createConfig } from "ponder";

export default createConfig({
  chains: {
    mainnet: {
      id: 1,
      rpc: process.env.PONDER_RPC_URL_1,
      pollingInterval: 1000,
    },
  },
  contracts: { /* ... */ },
});

// Relevant knobs for BSC:
//   ethGetLogsBlockRange  - override when auto-detection guesses wrong (blockrazor=25, nodereal=50000)
//   pollingInterval       - default 1000ms == ~2.2 BSC blocks of lag; lower it
//   ws                    - WebSocket with automatic fallback to polling
//   disableCache          - required when pointing at Anvil
